function initials(string $name): string {
    $parts = preg_split('/\s+/', trim($name));
    $first = preg_match('/^./us', $parts[0] ?? 'H', $match) ? $match[0] : 'H';
    $last = count($parts) > 1 && preg_match('/^./us', end($parts), $match) ? $match[0] : '';
    return strtoupper($first . $last);
}
function avatar_content(array $user): string {
    if (profile_photo_path($user)) { return '<img src="' . e(url('photo')) . '" alt="" class="profile-photo">'; }
    return '<span aria-hidden="true">' . e(initials($user['name'])) . '</span>';
}
