function detail_fetch(): bool { return ($_SERVER['HTTP_X_DETAIL_MODAL'] ?? '') === '1'; }
function modal_request(): bool { return ($_SERVER['REQUEST_METHOD'] ?? '') === 'GET' && (($_GET['modal'] ?? '') === '1' || detail_fetch()); }
// Em pedidos do modal só o conteúdo do detalhe é devolvido, sem o layout da página.
function detail_start(string $title, string $active, bool $forms = false): void {
    if (!modal_request()) { page_start($title, $active); return; }
    echo '<div data-detail-fragment' . ($forms ? ' data-detail-forms' : '') . '>';
    if (!empty($_SESSION['flash'])) { $flash = $_SESSION['flash']; unset($_SESSION['flash']); echo '<div class="notice notice-' . e($flash['type']) . '" role="status">' . icon($flash['type'] === 'success' ? 'check' : 'file') . '<span>' . e($flash['message']) . '</span></div>'; }
}
function detail_end(): void { if (modal_request()) { echo '</div>'; return; } page_end(); }
