function render_subject_cards(array $subjects): void {
    $unassigned = (int) query('SELECT COUNT(*) FROM hc_portal_files WHERE subject_id IS NULL AND deleted_at IS NULL')->fetchColumn();
    $cards = array_map(fn($item) => ['url' => subject_url($item['id']), 'name' => $item['name'], 'description' => $item['description'] ?: 'Explore os materiais desta matéria.', 'color' => $item['color'] ?: 'orange', 'count' => (int) $item['file_count']], $subjects);
    if ($unassigned > 0) { $cards[] = ['url' => url('unassigned'), 'name' => 'Sem matéria', 'description' => 'Materiais preservados, disponíveis para consulta e realocação em outra matéria.', 'color' => '', 'count' => $unassigned]; }
    if (!$cards): ?><div class="empty-state"><span class="empty-icon"><?= icon('folder') ?></span><h3>Nenhuma matéria cadastrada</h3><p>As matérias aparecerão aqui quando forem criadas.</p></div><?php return; endif; ?>
<section class="subject-cards" aria-label="Matérias"><?php foreach ($cards as $card): ?><article class="subject-card"><span class="subject-card-mark <?= $card['color'] !== '' ? 'color-' . e($card['color']) : '' ?>" aria-hidden="true"></span><h2 class="subject-card-title"><a data-library-link href="<?= e($card['url']) ?>"><?= e($card['name']) ?></a></h2><p class="subject-card-description"><?= e($card['description']) ?></p><span class="subject-card-meta"><?= icon('file') ?><?= $card['count'] ?> <?= $card['count'] === 1 ? 'material' : 'materiais' ?></span></article><?php endforeach; ?></section>
<?php }
