<a class="back-link" data-reading-back href="<?= e($file['folder_id'] === null ? subject_url($file['subject_id']) : url('folder', ['id' => $file['folder_id']])) ?>"><?= icon('back') ?><?= e($file['subject_name'] ?? 'Sem matéria') ?></a><div class="page-heading viewer-heading"><div><span class="eyebrow"><?= e(strtoupper($file['extension'])) ?> · <?= e(pretty_size((int) $file['size'])) ?></span><h1><?= e($file['title']) ?></h1><?php render_kind_badge($file); render_study_badge($file); ?><p><?= e($file['original_name']) ?></p></div><div class="heading-actions"><button type="button" class="button button-secondary" data-reading-expand><?= icon('expand') ?>Expandir leitura</button><?php if (can_preview($file)): ?><a class="button button-secondary" href="<?= e(url('file', ['id' => $file['id']])) ?>" target="_blank" rel="noopener"><?= icon('external') ?>Abrir em outra aba</a><?php endif; ?><a class="button button-primary" href="<?= e(url('file', ['id' => $file['id'], 'download' => 1])) ?>"><?= icon('download') ?>Baixar arquivo</a></div></div>
<?php render_study_form('file', $file, url('view', ['id' => $file['id']])); ?>
<?php if ($manage): ?>
<div class="material-toolbar"><a class="button button-secondary" href="<?= e(url('edit-material', ['id' => $file['id']])) ?>"><?= icon('edit') ?>Editar material</a><button class="button button-danger" data-open="delete-material-dialog"><?= icon('trash') ?>Excluir material</button></div>
<dialog id="delete-material-dialog" class="modal" aria-labelledby="delete-material-title"><div class="modal-heading"><h2 id="delete-material-title">Excluir material?</h2><button class="icon-button" data-close aria-label="Fechar"><?= icon('close') ?></button></div><p>“<?= e($file['title']) ?>” deixará de aparecer para todas as contas. Seus links de visualização e download serão bloqueados.</p><form method="post" action="<?= e(url('delete-material')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= (int) $file['id'] ?>"><input type="hidden" name="revision" value="<?= (int) $file['revision'] ?>"><label class="delete-confirmation"><input type="checkbox" name="confirm" value="1" required>Confirmo a exclusão deste material do portal.</label><div class="modal-actions"><button type="button" class="button button-secondary" data-close>Cancelar</button><button type="submit" class="button button-danger"><?= icon('trash') ?>Excluir do portal</button></div></form></dialog>
<?php endif; ?>
<?php if (can_preview($file)): $isHtml = in_array($file['extension'], ['html', 'htm'], true); ?><div class="document-viewer"><iframe title="<?= e($file['title']) ?>" src="<?= e(url('file', ['id' => $file['id']])) ?>" <?= $isHtml ? 'sandbox="allow-scripts allow-forms allow-modals allow-popups allow-downloads' . (($file['trusted_app'] && $file['source'] === 'legacy') ? ' allow-same-origin' : '') . '"' : '' ?> allowfullscreen></iframe></div><?php else: ?><div class="empty-state document-fallback"><span class="empty-icon"><?= icon('file') ?></span><h2>Pronto para levar com você</h2><p>Baixe este arquivo para abrir no aplicativo da sua preferência.</p><a class="button button-primary" href="<?= e(url('file', ['id' => $file['id'], 'download' => 1])) ?>"><?= icon('download') ?>Baixar arquivo</a></div><?php endif; ?></div><?php page_end((int) $file['subject_id']);
}
