function render_password(array $user): void {
    page_start('Minha conta', 'password'); ?>
<div class="page-heading"><div><span class="eyebrow">SEU ACESSO</span><h1><?= (int) $user['must_change_password'] ? 'Crie sua própria senha' : 'Minha conta' ?></h1><p><?= (int) $user['must_change_password'] ? 'Antes de continuar, substitua a senha temporária por uma senha só sua.' : 'Cuide do seu acesso ao espaço de estudos.' ?></p></div></div><?php if (!(int) $user['must_change_password'] && two_factor_required($user) && !two_factor_active($user)): ?><div class="notice notice-error" role="alert" data-two-factor-required><?= icon('lock') ?><span>Administradores precisam da validação em 2 etapas. Ative-a abaixo para continuar usando o portal.</span></div><?php endif; ?><section class="form-card account-card"><?php $photoEnabled = !(int) $user['must_change_password']; ?><div class="account-summary"><?php if ($photoEnabled) { render_photo_form($user); } else { ?><span class="avatar avatar-large"><?= avatar_content($user) ?></span><?php } ?><div><h2><?= e($user['name']) ?></h2><p class="muted"><?= e($user['login']) ?></p><?php if ($photoEnabled) { render_photo_details($user); } ?></div></div><div class="account-sections"><?php if ($photoEnabled) { render_account_security($user); } ?><section class="account-password"><h3 class="account-password-heading">Alterar senha</h3><form method="post" action="<?= e(url('password')) ?>"><?= csrf() ?><label>Senha atual<input type="password" name="current_password" autocomplete="current-password" required></label><label>Nova senha<input type="password" name="password" data-new-password minlength="12" maxlength="72" autocomplete="new-password" required></label><label>Confirme a nova senha<input type="password" name="password_confirmation" data-new-password minlength="12" maxlength="72" autocomplete="new-password" required></label><button class="button button-primary" type="submit"><?= icon('lock') ?>Salvar nova senha</button></form></section></div></section><?php page_end();
}
function render_users(): void {
    $users = query('SELECT id, name, login, role, active, created_at FROM hc_portal_users ORDER BY active DESC, name')->fetchAll(); page_start('Gerenciar contas', 'users'); ?>
<div class="page-heading"><div><span class="eyebrow">APRENDER É MELHOR EM COMPANHIA</span><h1>Quem estuda por aqui</h1><p>Crie contas para compartilhar a mesma biblioteca de materiais.</p></div><button class="button button-primary" data-open="user-dialog"><?= icon('plus') ?>Nova conta</button></div><div class="notice notice-info"><?= icon('users') ?><span>Usuários normais podem apenas visualizar e baixar materiais. Somente administradores gerenciam matérias, materiais e contas.</span></div><div class="users-grid"><?php foreach ($users as $item): ?><section class="user-card"><div class="user-card-heading"><span class="avatar avatar-large"><?= e(initials($item['name'])) ?></span><span class="status-pill <?= (int) $item['active'] ? 'status-active' : 'status-inactive' ?>"><?= (int) $item['active'] ? 'Ativa' : 'Desativada' ?></span></div><h2><?= e($item['name']) ?></h2><p class="muted"><?= e($item['login']) ?></p><span class="user-role"><?= icon($item['role'] === 'admin' ? 'lock' : 'user') ?><?= $item['role'] === 'admin' ? 'Administrador' : 'Estudante' ?></span><?php if ((int) $item['id'] !== (int) current_user()['id']): ?><div class="user-card-actions"><form method="post" action="<?= e(url('update-user')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="action" value="toggle"><button type="submit" class="text-button" data-confirm="<?= (int) $item['active'] ? 'Desativar esta conta e encerrar suas sessões?' : 'Reativar esta conta?' ?>"><?= (int) $item['active'] ? 'Desativar conta' : 'Reativar conta' ?></button></form><form method="post" action="<?= e(url('update-user')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="confirm" value="1"><button type="submit" class="text-button" data-swal-confirm data-swal-title="Deseja realmente excluir?">Excluir conta</button></form><details class="password-reset"><summary>Redefinir senha</summary><form method="post" action="<?= e(url('update-user')) ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="action" value="reset"><label>Senha temporária<input type="password" name="password" data-new-password minlength="12" maxlength="72" autocomplete="new-password" required></label><button class="button button-small button-secondary">Redefinir</button></form></details></div><?php else: ?><a class="text-button own-account" href="<?= e(url('password')) ?>">Esta é sua conta<?= icon('arrow') ?></a><?php endif; ?></section><?php endforeach; ?></div>
<dialog id="user-dialog" class="modal"><div class="modal-heading"><div><span class="eyebrow">COMPARTILHE CONHECIMENTO</span><h2>Nova conta</h2></div><button class="icon-button" data-close aria-label="Fechar"><?= icon('close') ?></button></div><form method="post" action="<?= e(url('create-user')) ?>"><?= csrf() ?><label>Nome<input name="name" maxlength="120" autocomplete="name" required></label><label>Usuário ou e-mail<input name="login" minlength="3" maxlength="100" autocomplete="off" pattern="[a-zA-Z0-9][a-zA-Z0-9._@+\-]{2,99}" required></label><label>Senha temporária<input type="password" name="password" data-new-password minlength="12" maxlength="72" autocomplete="new-password" required></label><p class="form-hint">Pelo menos 12 caracteres e até 72 bytes. Acentos e símbolos podem ocupar mais de um byte. A pessoa trocará a senha no primeiro acesso.</p><label>Tipo de acesso<select name="role"><option value="member">Estudante</option><option value="admin">Administrador</option></select></label><div class="modal-actions"><button type="button" class="button button-secondary" data-close>Cancelar</button><button class="button button-primary">Criar conta</button></div></form></dialog><?php page_end();
}
